    private static readonly Lazy<Dictionary<string, LearnedHeadphoneProfile>> _byProductId = new(() =>
    {
        var dict = new Dictionary<string, LearnedHeadphoneProfile>(StringComparer.OrdinalIgnoreCase);
        foreach (var p in WearingStyleTop200) dict.TryAdd(p.ProductId, p);
        foreach (var p in DriverTypeTop200) dict.TryAdd(p.ProductId, p);
        foreach (var p in TuningStyleTop200) dict.TryAdd(p.ProductId, p);
        return dict;
    });

    public static IReadOnlyList<LearnedHeadphoneProfile> GetDistinctCatalog()
        => _byProductId.Value.Values.OrderByDescending(p => p.MeasurementCount).ThenBy(p => p.DisplayName).ToList();

    public static LearnedHeadphoneProfile? FindByProductOrPresetId(string? idOrName)
    {
        if (string.IsNullOrWhiteSpace(idOrName)) return null;
        if (_byProductId.Value.TryGetValue(idOrName, out var exact)) return exact;
        string normalized = idOrName.Trim();
        int splitIdx = normalized.IndexOf("::", StringComparison.Ordinal);
        int thirdColon = splitIdx >= 0 ? normalized.IndexOf("::", splitIdx + 2, StringComparison.Ordinal) : -1;
        if (thirdColon > 0)
        {
            string prodCandidate = normalized[..thirdColon];
            if (_byProductId.Value.TryGetValue(prodCandidate, out var prodHit)) return prodHit;
        }
        foreach (var p in _byProductId.Value.Values)
        {
            if (string.Equals(p.DisplayName, normalized, StringComparison.OrdinalIgnoreCase)) return p;
        }
        return null;
    }

    /// <summary>
    /// Infers acoustic attributes dynamically even for OPRA products outside the 600 flagship subset.
    /// </summary>
    public static LearnedHeadphoneProfile InferFromOpraPreset(OpraHeadphonePreset preset, string? subtype = null)
    {
        if (preset == null) return WearingStyleTop200[0];
        var hit = FindByProductOrPresetId(preset.ProductId) ?? FindByProductOrPresetId(preset.Id) ?? FindByProductOrPresetId($"{preset.Brand} {preset.Model}");
        if (hit != null) return hit;

        double[] evalFreqs = { 40, 110, 280, 750, 1800, 4000, 8000, 14000 };
        double[] eqDb = new double[8];
        foreach (var f in preset.Filters)
        {
            var bq = new FurinaPlayerBiquadFilter { FilterType = f.Type, FrequencyHz = f.FrequencyHz, GainDb = f.GainDb, Q = f.Q, Enabled = true };
            bq.UpdateCoefficients(48000.0);
            for (int i = 0; i < 8; i++) eqDb[i] += bq.CalculateResponseDb(evalFreqs[i], 48000.0);
        }
        double midBias = -eqDb[3];
        double sub = Math.Round(-eqDb[0] - midBias, 2);
        double mb = Math.Round(-eqDb[1] - midBias, 2);
        double lm = Math.Round(-eqDb[2] - midBias, 2);
        double um = Math.Round(-eqDb[4] - midBias, 2);
        double pr = Math.Round(-eqDb[5] - midBias, 2);
        double br = Math.Round(-eqDb[6] - midBias, 2);
        double air = Math.Round(-eqDb[7] - midBias, 2);
        double peak = Math.Max(0.0, eqDb.Max());

        string text = $"{preset.Brand} {preset.Model} {preset.Details}".ToLowerInvariant();
        HeadphoneWearingStyle wearing = subtype == "earbuds" ? HeadphoneWearingStyle.Earbud
            : (subtype == "on_ear" || subtype == "on_the_ear" ? HeadphoneWearingStyle.OnEar
            : (subtype == "in_ear" || subtype == "in_the_ear"
                ? (text.Contains("tws") || text.Contains("airpods") || text.Contains("buds") || text.Contains("wf-") ? HeadphoneWearingStyle.TrueWireless : HeadphoneWearingStyle.InEarIem)
                : HeadphoneWearingStyle.OverEar));

        HeadphoneDriverType driver = text.Contains("stax") || text.Contains("sr-00") || text.Contains("sr-l") ? HeadphoneDriverType.Electrostatic
            : (text.Contains("hifiman") || text.Contains("audeze") || text.Contains("sundara") || text.Contains("arya") || text.Contains("lcd") || text.Contains("planar") || text.Contains("timeless") || text.Contains("s12") ? HeadphoneDriverType.PlanarMagnetic
            : (text.Contains("64 audio") || text.Contains("monarch") || text.Contains("blessing") || text.Contains("hexa") || text.Contains("z1r") ? HeadphoneDriverType.HybridTribrid
            : (text.Contains("etymotic") || text.Contains("shure se") || text.Contains("andromeda") || text.Contains("ier-m") ? HeadphoneDriverType.BalancedArmature : HeadphoneDriverType.Dynamic)));

        double bassAvg = sub * 0.6 + mb * 0.4;
        double trebAvg = (pr + br) * 0.5;
        double trebPeak = Math.Max(br, trebAvg);
        HeadphoneTuningStyle tuning = ((br >= 2.2 || trebPeak >= 1.8) && (bassAvg >= 1.3 || mb >= 2.2)) ? HeadphoneTuningStyle.VShaped
            : (trebPeak >= 1.7 && bassAvg < 1.35 ? HeadphoneTuningStyle.BrightAnalytical
            : ((bassAvg >= 2.0 || (sub >= 2.5 && mb >= 1.5)) && trebPeak <= bassAvg + 1.2 ? HeadphoneTuningStyle.BassHeavy
            : (mb >= 0.7 && br <= -0.3 ? HeadphoneTuningStyle.WarmLush
            : (Math.Abs(bassAvg) < 2.0 && Math.Abs(trebAvg) < 2.0 ? HeadphoneTuningStyle.HarmanNeutral : HeadphoneTuningStyle.MidCentricVocal))));

        return new LearnedHeadphoneProfile(preset.ProductId, preset.Brand, preset.Model, wearing, driver, tuning, 1, sub, mb, lm, um, pr, br, air, Math.Round(peak, 2));
    }
